#include "target-catalog.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static struct cl_target_capture capture;
static unsigned calls,checks;static int reject_pre,drift,lost_reap,helper_ok=1;
static const char secret[]="postgres://PRIVATE_TARGET_DSN@postgres/db";
static int current(void*c,const struct cl_target_request*r,int effect){(void)c;assert(r->epoch==3);assert(effect==(r->opcode==16||r->opcode==17));checks++;return !reject_pre;}
static int guards(void*c){(void)c;return !(drift&&calls);}
static int engine(void*c,struct cl_target_string e){(void)c;return e.n==6&&!memcmp(e.p,"engine",6);}
static int helper(void*c,const struct cl_target_request*r,const struct cl_target_helper*h){(void)c;assert(h->opcode==r->opcode);return helper_ok;}
static int database_url(void*c,const struct cl_target_request*r,unsigned char*out,size_t cap,size_t*n){(void)c;(void)r;assert(cap>=sizeof(secret));memcpy(out,secret,sizeof(secret)-1);*n=sizeof(secret)-1;return 1;}
static int run(void*c,const struct cl_target_plan*p,unsigned char*out,size_t cap,struct cl_target_result*r){(void)c;calls++;assert(!strcmp(p->argv[0],"--host"));assert(!strcmp(p->argv[1],"npipe:////./pipe/dockerDesktopLinuxEngine"));assert(!strcmp(p->argv[3],"D:\\held-config"));if(p->opcode==15){assert(p->argc==7);assert(!strcmp(p->argv[4],"container"));assert(!strcmp(p->argv[5],"inspect"));assert(p->timeout==10000&&cap==262144&&p->input_bytes==0);}else{assert(p->argc==12);assert(!strcmp(p->argv[4],"exec"));assert(!strcmp(p->argv[7],"/usr/bin/env"));assert(!strcmp(p->argv[8],"-i"));assert(!strcmp(p->argv[9],"/usr/local/bin/node"));assert(!strcmp(p->argv[10],"-e"));assert(strstr(p->argv[11],"/app/scripts/setup-database-v1.mjs"));assert(p->timeout==120000&&cap==2048);assert(p->input_bytes>100&&p->input_bytes<2048);assert(memmem(p->input,p->input_bytes,"\"schemaVersion\":1,",18));assert(memmem(p->input,p->input_bytes,"PRIVATE_TARGET_DSN",18));assert(memmem(p->input,p->input_bytes,"\"phase\":\"seed\"",14));}memcpy(out,secret,sizeof(secret)-1);r->bytes=sizeof(secret)-1;r->reaped=!lost_reap;return 1;}
static void reset(void){cl_target_abort(&capture);calls=checks=0;reject_pre=drift=lost_reap=0;helper_ok=1;}
static void zero(void){size_t i;assert(!capture.active);for(i=0;i<sizeof(capture.output);i++)assert(capture.output[i]==0);for(i=0;i<sizeof(capture.input);i++)assert(capture.input[i]==0);}
int main(int argc,char**argv){unsigned char body[CL_TARGET_REQUEST_MAX],out[60];size_t n,got;int done;FILE*f;struct cl_target_request parsed;struct cl_target_helper helpers[3]={{16,"/app/scripts/setup-database-v1.mjs",{1}},{17,"/app/scripts/super-admin-owner.mjs",{2}},{18,"/app/scripts/setup-observe-v1.mjs",{3}}};struct cl_target_ops ops={0,"D:\\held-config",helpers,3,current,guards,engine,helper,database_url,run};assert(argc==2);f=fopen(argv[1],"rb");assert(f);n=fread(body,1,sizeof(body),f);assert(!ferror(f)&&feof(f));fclose(f);assert(cl_target_parse(body,n,&parsed));reset();assert(cl_target_begin(&capture,&ops,7,body,n)==0);assert(calls==1&&checks==2);assert(cl_target_read(&capture,8,0,out,sizeof(out),&got,&done)==4);assert(capture.active);assert(cl_target_cancel(&capture,8)==4&&capture.active);assert(cl_target_read(&capture,7,0,out,7,&got,&done)==0&&got==7&&!done);assert(!memcmp(out,secret,7));assert(cl_target_read(&capture,7,7,out,sizeof(out),&got,&done)==0&&done);assert(!memcmp(out,secret+7,got));zero();reset();assert(cl_target_begin(&capture,&ops,9,body,n)==0);assert(cl_target_read(&capture,9,1,out,sizeof(out),&got,&done)==5);zero();reset();reject_pre=1;assert(cl_target_begin(&capture,&ops,10,body,n)==4&&calls==0);reset();drift=1;assert(cl_target_begin(&capture,&ops,11,body,n)==5&&calls==1);zero();reset();lost_reap=1;assert(cl_target_begin(&capture,&ops,12,body,n)==5&&calls==1);zero();reset();body[8]=16;body[10]=1;helper_ok=0;assert(cl_target_begin(&capture,&ops,13,body,n)==4&&calls==0);helper_ok=1;assert(cl_target_begin(&capture,&ops,13,body,n)==0);assert(cl_target_cancel(&capture,13)==5);zero();reset();body[9]=2;assert(!cl_target_parse(body,n,&parsed));body[9]=0;body[n++]=0;assert(!cl_target_parse(body,n,&parsed));puts("fixed-target-native-controls PASS");return 0;}
